import FormItemLabel from '../FormItemLabel'
import { DatePickerStyle } from './index.style'
import { LANG_STRINGS } from '../../../../lang/index'
import { CustomText } from '../../..'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { useCallback, useState, useEffect } from 'react'
import { Datepicker, setOptions } from '@mobiscroll/react'
import { Error } from '../../../../commonStyle/index.style'
import { MINI_INFO } from '../../../../images'

setOptions({
  theme: 'ios',
  themeVariant: 'light'
})

const DISABLED_WEEKDAYS = [
  {
    recurring: {
      repeat: 'weekly',
      weekDays: 'SA,SU' // disabled weekday
    }
  }
]

function DatePicker ({
  title, name, required, minDate, maxDate,
  getSubText, onChange = () => {}, error,
  defaultValue = new Date(), invalid = ''
}) {
  const defaultSelection = defaultValue || new Date()
  const [selected, setSelected] = useState()

  useEffect(() => {
    if (defaultValue && !selected) {
      setSelected(defaultValue)
      onChange({
        name,
        value: defaultValue
      })
    }
  }, [selected, name, onChange, defaultValue])

  const handleOnChange = useCallback((e) => {
    setSelected(e.value)
    onChange({
      name,
      value: e.value
    })
  }, [name, onChange])

  return (
    <DatePickerStyle
      error={error}
    >
      <FormItemLabel
        title={title}
        required={required}
      />
      {/* <input
        name={name}
        ref={inputRef}
        placeholder={LANG_STRINGS.select}
      /> */}
      <Datepicker
        touchUi
        dateFormat='DD/MM/YYYY'
        inputComponent='input'
        controls={['date']}
        className='date-input'
        defaultSelection={defaultSelection}
        inputProps={{
          placeholder: LANG_STRINGS.select,
          className: 'md-mobile-picker-input'
        }}
        theme='ios'
        themeVariant='light'
        min={minDate}
        max={maxDate}
        defaultValue={selected}
        onChange={handleOnChange}
        invalid={(invalid === 'weekends') ? DISABLED_WEEKDAYS : []}
      />
      {
        getSubText && (
          <CustomText
            color={AgentColorPallette.fontGrey}
            size='0.7em'
            top='0.4rem'
            className='display-flex'
          >
            <img src={MINI_INFO} alt='Info' className='align-self' />&nbsp;&nbsp;<span>{getSubText(selected)}</span>
          </CustomText>
        )
      }
      <Error>{error}</Error>
    </DatePickerStyle>
  )
}

export default DatePicker
