import { TRAVEL_PROTECTION } from '../../../../constants/pkgCode'
import { formatDate } from '../../../../helpers/formatDate'
import { formatMoney } from '../../../../helpers/utility'

const CONTENT_DATA_V1 = [
  {
    label: 'Pemegang Polis',
    render: (data) => data?.customer_data?.name || '-',
  },
  {
    label: 'Total Premi',
    render: (data) => formatMoney(data?.total_premium, 0) || '-',
  },
  {
    label: 'Awal Perlindungan',
    render: (data) => formatDate(data?.policy_detail?.start_date, 'DD/MM/YYYY') || '-',
  },
  {
    label: 'Kategori Asuransi',
    render: (data) => data?.product?.package?.product?.name || '-',
  },
  {
    label: 'Akhir Perlindungan',
    render: (data) => formatDate(data?.policy_detail?.end_date, 'DD/MM/YYYY') || '-',
  },
  {
    label: 'Penyedia Asuransi',
    render: (data) => data?.product?.provider?.name || '-',
  },
]

const CONTENT_DATA_V2 = [
  {
    label: 'Pemegang Polis',
    render: (data) => data?.customer_data?.name || '-',
  },
  {
    label: 'Total Premi',
    render: (data) => formatMoney(data?.total_premium, 0) || '-',
  },
  {
    label: 'Awal Perlindungan',
    render: (data) => formatDate(data?.policy_detail?.period?.start_date, 'DD/MM/YYYY') || '-',
  },
  {
    label: 'Kategori Asuransi',
    render: (data) => data?.policy_detail?.package?.product?.name || '-',
  },
  {
    label: 'Akhir Perlindungan',
    render: (data) => formatDate(data?.policy_detail?.period?.end_date, 'DD/MM/YYYY') || '-',
  },
  {
    label: 'Penyedia Asuransi',
    render: (data) => data?.policy_detail?.package?.provider?.name || '-',
  },
]

export const getContentData = (productKey) => {
  switch (productKey) {
    case TRAVEL_PROTECTION:
      return CONTENT_DATA_V2
    default:
      return CONTENT_DATA_V1
  }
}
