import { useEffect, useMemo, useState } from 'react'
import { useHistory } from 'react-router-dom'
import { useParams } from 'react-router'
import { connect } from 'react-redux'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Container } from '../../../../../components'
import ProductBottomSheet from '../../../../../components/ProductBottomSheet'
import { PAYMENT_GATEWAY } from '../../../../../constants/payment'
import { useGetPaymentStatusReq } from '../../../../Private/Payments/state/hooks/usePaymentState'
import { getQueryParams } from '../../../../../helpers/utility'
import customerActions from '../../../../../redux/customer/actions'
import ContentSuccess from '../components/ContentSuccess'
import ContentFailed from '../components/ContentFailed'
import ContentInProgress from '../components/ContentInProgress'
import { PaymentSuccessStyle } from './index.style'

const PAYMENT_STATE = {
  IN_PROGRESS: 'IN_PROGRESS',
  SUCCESS: 'SUCCESS',
  FAILED: 'FAILED',
}

function PaymentSuccessContainer(props) {
  const { customerPolicy, customerPolicyLoader, getCustomerPolicyReq } = props

  const history = useHistory()
  const { policyId, transactionId } = useParams()
  const source = useMemo(() => getQueryParams('source') || PAYMENT_GATEWAY, [])

  const [paymentState, setPaymentState] = useState(PAYMENT_STATE.IN_PROGRESS)
  const [showProductModal, setShowProductModal] = useState()

  const [{ getPaymentStatusData = {} }, getPaymentStatusReq] =
    useGetPaymentStatusReq()
  const [{ GET_PAYMENT_STATUS_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    getCustomerPolicyReq(policyId)
    getPaymentStatusReq({
      transactionId: transactionId,
      query: { source: source },
    })
  }, [
    policyId,
    transactionId,
    source,
    getCustomerPolicyReq,
    getPaymentStatusReq,
  ])

  useEffect(() => {
    const policyStatus = customerPolicy.status
    const policyPaymentStatus = customerPolicy.payment_status
    const paymentStatus = getPaymentStatusData.payment_status

    switch (true) {
      case paymentStatus === 'ACTIVE':
      case [policyPaymentStatus, policyStatus].includes('PAYMENT_PENDING'):
        setPaymentState(PAYMENT_STATE.IN_PROGRESS)
        break
      case paymentStatus === 'COMPLETED':
        setPaymentState(PAYMENT_STATE.SUCCESS)
        break
      case paymentStatus === 'EXPIRED':
      default:
        setPaymentState(PAYMENT_STATE.FAILED)
        break
    }
  }, [customerPolicy, getPaymentStatusData])

  return (
    <Container
      loader={customerPolicyLoader || GET_PAYMENT_STATUS_LOADER}
      mitraHeader
      hideBottomTabs
      hideGuardianInfo
      hideBackButton
      closeIcon
      onClose={() => history.push('/dashboard')}
    >
      {customerPolicy?.id && (
        <PaymentSuccessStyle>
          {paymentState === PAYMENT_STATE.IN_PROGRESS && (
            <ContentInProgress policyDetail={customerPolicy} />
          )}
          {paymentState === PAYMENT_STATE.SUCCESS && (
            <ContentSuccess policyDetail={customerPolicy} />
          )}
          {paymentState === PAYMENT_STATE.FAILED && (
            <ContentFailed policyDetail={customerPolicy} />
          )}
        </PaymentSuccessStyle>
      )}
      {showProductModal && (
        <ProductBottomSheet
          show={showProductModal}
          onClose={() => setShowProductModal(false)}
        />
      )}
    </Container>
  )
}

export default connect(
  (state) => ({
    customerPolicy: state.Customer.customerPolicyData,
    customerPolicyDataStatus: state.Customer.customerPolicyDataStatus,
    customerPolicyLoader: state.Loading.GET_CUSTOMER_POLICY,
  }),
  {
    getCustomerPolicyReq: customerActions.getCustomerPolicy,
  }
)(PaymentSuccessContainer)
