import { useEffect } from 'react'
import { getContentData } from '../helpers'
import { GREEN_CHECK_LINE } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { ContentStyle, PolicyDetailSection } from '../container/index.style'
import useEventTracker from '../../../../../hooks/trackers'

function ContentSuccess({ policyDetail }) {
  const contentData = getContentData(policyDetail?.product_key)
  const { trackUserEvent } = useEventTracker()

  useEffect(() => {
    if (!policyDetail) return
    trackUserEvent(`[Mitra] Enter Success Page`, {
      draft_id: policyDetail.policy_detail?.draft_id || null,
      application_no: policyDetail.application_no || null,
      product_key: policyDetail.product_key || null,
    })
  }, [policyDetail, trackUserEvent])

  return (
    <ContentStyle>
      <img src={GREEN_CHECK_LINE} alt="" />
      <div className="title title-success">{LANG_STRINGS.transactionSuccess}</div>
      <div className="subtitle">
        Selamat! Anda berhasil menyelesaikan transaksi baru! Terus berjualan, tingkatkan GWP Anda
        dan raih hadiah jalan-jalan ke luar negeri!
      </div>

      <PolicyDetailSection>
        <div className="__header">
          <div>{LANG_STRINGS.policyNumber}</div>
          <div>{policyDetail?.application_no}</div>
        </div>
        <div className="__body">
          {contentData.map((_data, i) => (
            <div key={i} className={`content-data ${i % 2 === 0 ? 'text-left' : 'text-right'}`}>
              <div className="__label">{_data.label}</div>
              <div className="__data">{_data.render(policyDetail)}</div>
            </div>
          ))}
        </div>
        <hr />
        <div className="__footer">
          <div className="content-data">
            <div className="__label">{LANG_STRINGS.policyDetailSendTo}</div>
            <div className="__data-lg">{policyDetail?.customer_data?.email}</div>
          </div>
        </div>
      </PolicyDetailSection>
    </ContentStyle>
  )
}

export default ContentSuccess
