import { DYNAMIC_PURCHASE_FLOW_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.SET_CONTEXT_STATE:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.RESET_CONTEXT_STATE:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_PURCHASE_FLOW_CONFIG:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_PACKAGE_LIST:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_PACKAGE_DETAIL:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_POLICY_DRAFT:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.CREATE_POLICY_DRAFT:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.UPDATE_POLICY_DRAFT:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.COMPLETE_POLICY_DRAFT:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_POLICY_APPLICATION_DETAIL:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.SHARE_QUOTATION_SLIP:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.UPLOAD_BULK_EXCEL:
    case DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_POPUP_API_OPTIONS:
      return {
        ...state,
        ...payload,
      }
    default:
      return {
        ...(state || {}),
      }
  }
}

export default reducer
